/* Lightweight Offline Chart Engine for Fuelbook (Doughnut, Line, Stacked Bar) */
(function(global) {
  function Chart(ctx, config) {
    this.ctx = ctx;
    this.config = config;
    this.canvas = ctx.canvas;
    this.draw();
  }
  Chart.prototype.destroy = function() {
    if (this.ctx && this.canvas) {
      this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    }
  };
  Chart.prototype.draw = function() {
    const canvas = this.canvas;
    const parent = canvas.parentElement;
    const dpr = window.devicePixelRatio || 1;
    const width = (parent ? parent.clientWidth : 320) || 320;
    const height = (parent ? parent.clientHeight : 210) || 210;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    canvas.style.width = width + 'px';
    canvas.style.height = height + 'px';
    const ctx = this.ctx;
    ctx.save();
    ctx.scale(dpr, dpr);
    ctx.clearRect(0, 0, width, height);

    const type = this.config.type;
    if (type === 'doughnut') this.drawDoughnut(ctx, width, height);
    else if (type === 'line') this.drawLine(ctx, width, height);
    else if (type === 'bar') this.drawStackedBar(ctx, width, height);
    ctx.restore();
  };

  Chart.prototype.drawDoughnut = function(ctx, w, h) {
    const data = (this.config.data.datasets[0] && this.config.data.datasets[0].data) || [];
    const labels = this.config.data.labels || [];
    const colors = (this.config.data.datasets[0] && this.config.data.datasets[0].backgroundColor) || ['#0D796A'];
    const borderColor = (this.config.data.datasets[0] && this.config.data.datasets[0].borderColor) || '#FFFFFF';
    const legendColor = (this.config.options && this.config.options.plugins && this.config.options.plugins.legend && this.config.options.plugins.legend.labels && this.config.options.plugins.legend.labels.color) || '#64777D';

    const total = data.reduce((a, b) => a + b, 0);
    if (total <= 0) return;

    const chartW = Math.min(w * 0.52, h);
    const cx = chartW / 2 + 6;
    const cy = h / 2;
    const rOuter = Math.max(24, Math.min(chartW, h) * 0.44);
    const rInner = rOuter * 0.56;

    let start = -Math.PI / 2;
    for (let i = 0; i < data.length; i++) {
      const slice = (data[i] / total) * Math.PI * 2;
      ctx.beginPath();
      ctx.arc(cx, cy, rOuter, start, start + slice);
      ctx.arc(cx, cy, rInner, start + slice, start, true);
      ctx.closePath();
      ctx.fillStyle = colors[i % colors.length];
      ctx.fill();
      ctx.lineWidth = 1.5;
      ctx.strokeStyle = borderColor;
      ctx.stroke();
      start += slice;
    }

    // Center total label
    ctx.fillStyle = legendColor;
    ctx.font = 'bold 11px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(labels.length + ' cat.', cx, cy);

    // Right legend
    const legX = chartW + 16;
    const maxItems = Math.min(labels.length, 8);
    const stepY = Math.min(22, (h - 16) / Math.max(1, maxItems));
    let legY = Math.max(14, (h - maxItems * stepY) / 2 + 6);
    ctx.textAlign = 'left';
    ctx.font = '11px sans-serif';
    for (let i = 0; i < maxItems; i++) {
      ctx.fillStyle = colors[i % colors.length];
      ctx.fillRect(legX, legY - 5, 10, 10);
      ctx.fillStyle = legendColor;
      const pct = Math.round((data[i] / total) * 100);
      let lbl = labels[i] + ' (' + pct + '%)';
      if (lbl.length > 18) lbl = labels[i].slice(0, 11) + '.. (' + pct + '%)';
      ctx.fillText(lbl, legX + 15, legY);
      legY += stepY;
    }
  };

  Chart.prototype.drawLine = function(ctx, w, h) {
    const labels = this.config.data.labels || [];
    const ds0 = this.config.data.datasets[0] || { data: [] };
    const ds1 = this.config.data.datasets[1] || null;
    const data = ds0.data || [];
    const txtColor = (this.config.options && this.config.options.scales && this.config.options.scales.x && this.config.options.scales.x.ticks && this.config.options.scales.x.ticks.color) || '#64777D';

    if (!data.length) return;
    const padL = 36, padR = 14, padT = 26, padB = 26;
    const plotW = w - padL - padR;
    const plotH = h - padT - padB;

    let allVals = data.slice();
    if (ds1 && ds1.data) allVals = allVals.concat(ds1.data);
    let minV = Math.min.apply(null, allVals);
    let maxV = Math.max.apply(null, allVals);
    if (minV === maxV) { minV = Math.max(0, minV - 2); maxV += 2; }
    else {
      const margin = (maxV - minV) * 0.15;
      minV = Math.max(0, minV - margin);
      maxV += margin;
    }

    // Legend top
    ctx.font = '11px sans-serif';
    ctx.fillStyle = ds0.borderColor || '#0D796A';
    ctx.fillRect(padL, 6, 12, 3);
    ctx.fillStyle = txtColor;
    ctx.textAlign = 'left';
    ctx.fillText(ds0.label || 'Mileage', padL + 16, 11);
    if (ds1) {
      ctx.fillStyle = ds1.borderColor || '#f59e0b';
      ctx.fillRect(padL + 115, 6, 12, 3);
      ctx.fillStyle = txtColor;
      ctx.fillText(ds1.label || 'Avg', padL + 131, 11);
    }

    // Grid & Y labels
    ctx.strokeStyle = 'rgba(130,145,150,0.2)';
    ctx.lineWidth = 1;
    ctx.fillStyle = txtColor;
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'right';
    for (let g = 0; g <= 3; g++) {
      const y = padT + (plotH * g) / 3;
      const val = maxV - ((maxV - minV) * g) / 3;
      ctx.beginPath();
      ctx.moveTo(padL, y);
      ctx.lineTo(w - padR, y);
      ctx.stroke();
      ctx.fillText(val.toFixed(1), padL - 5, y + 3);
    }

    const xFor = (i) => data.length === 1 ? padL + plotW / 2 : padL + (plotW * i) / (data.length - 1);
    const yFor = (v) => padT + plotH - ((v - minV) / (maxV - minV)) * plotH;

    // Avg dashed line
    if (ds1 && ds1.data && ds1.data.length) {
      ctx.save();
      ctx.setLineDash([5, 5]);
      ctx.strokeStyle = ds1.borderColor || '#f59e0b';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      for (let i = 0; i < ds1.data.length; i++) {
        const x = xFor(i), y = yFor(ds1.data[i]);
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.stroke();
      ctx.restore();
    }

    // Main line
    ctx.strokeStyle = ds0.borderColor || '#0D796A';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    for (let i = 0; i < data.length; i++) {
      const x = xFor(i), y = yFor(data[i]);
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // Points & X labels
    ctx.fillStyle = ds0.borderColor || '#0D796A';
    for (let i = 0; i < data.length; i++) {
      const x = xFor(i), y = yFor(data[i]);
      ctx.beginPath();
      ctx.arc(x, y, 3.8, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.fillStyle = txtColor;
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    const step = Math.max(1, Math.ceil(labels.length / 5));
    for (let i = 0; i < labels.length; i += step) {
      const lbl = labels[i].length > 8 ? labels[i].slice(0, 6) : labels[i];
      ctx.fillText(lbl, xFor(i), h - 8);
    }
  };

  Chart.prototype.drawStackedBar = function(ctx, w, h) {
    const labels = this.config.data.labels || [];
    const ds0 = this.config.data.datasets[0] || { data: [] };
    const ds1 = this.config.data.datasets[1] || { data: [] };
    const txtColor = (this.config.options && this.config.options.scales && this.config.options.scales.x && this.config.options.scales.x.ticks && this.config.options.scales.x.ticks.color) || '#64777D';

    if (!labels.length) return;
    const padL = 42, padR = 14, padT = 26, padB = 26;
    const plotW = w - padL - padR;
    const plotH = h - padT - padB;

    let maxSum = 0;
    for (let i = 0; i < labels.length; i++) {
      const s = (ds0.data[i] || 0) + (ds1.data[i] || 0);
      if (s > maxSum) maxSum = s;
    }
    if (maxSum <= 0) maxSum = 100;
    maxSum *= 1.15;

    // Legend
    ctx.font = '11px sans-serif';
    ctx.fillStyle = ds0.backgroundColor || '#0D796A';
    ctx.fillRect(padL, 6, 10, 10);
    ctx.fillStyle = txtColor;
    ctx.textAlign = 'left';
    ctx.fillText(ds0.label || 'Fuel', padL + 14, 15);

    ctx.fillStyle = ds1.backgroundColor || '#f59e0b';
    ctx.fillRect(padL + 85, 6, 10, 10);
    ctx.fillStyle = txtColor;
    ctx.fillText(ds1.label || 'Misc', padL + 99, 15);

    // Grid
    ctx.strokeStyle = 'rgba(130,145,150,0.2)';
    ctx.lineWidth = 1;
    ctx.fillStyle = txtColor;
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'right';
    for (let g = 0; g <= 3; g++) {
      const y = padT + (plotH * g) / 3;
      const val = maxSum - (maxSum * g) / 3;
      ctx.beginPath();
      ctx.moveTo(padL, y);
      ctx.lineTo(w - padR, y);
      ctx.stroke();
      const disp = val >= 1000 ? (val / 1000).toFixed(1) + 'k' : Math.round(val).toString();
      ctx.fillText(disp, padL - 5, y + 3);
    }

    const slotW = plotW / labels.length;
    const barW = Math.min(34, slotW * 0.58);
    const step = Math.max(1, Math.ceil(labels.length / 6));

    for (let i = 0; i < labels.length; i++) {
      const v0 = ds0.data[i] || 0;
      const v1 = ds1.data[i] || 0;
      const h0 = (v0 / maxSum) * plotH;
      const h1 = (v1 / maxSum) * plotH;
      const x = padL + i * slotW + (slotW - barW) / 2;
      const y0 = padT + plotH - h0;
      const y1 = y0 - h1;

      if (h0 > 0) {
        ctx.fillStyle = ds0.backgroundColor || '#0D796A';
        ctx.fillRect(x, y0, barW, h0);
      }
      if (h1 > 0) {
        ctx.fillStyle = ds1.backgroundColor || '#f59e0b';
        ctx.fillRect(x, y1, barW, h1);
      }

      if (i % step === 0) {
        ctx.fillStyle = txtColor;
        ctx.font = '10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(labels[i], padL + i * slotW + slotW / 2, h - 8);
      }
    }
  };

  global.Chart = Chart;
})(window);
